mapper.select:
select
mn.*
from Sys_Form mn

    
        and mn.Te_Id=#{params.teId}
    
    
        and mn.Sy_Type=#{params.syType}
    
    
        and mn.Sy_State=#{params.syState}
    
    
        and mn.T_Id=#{params.tId}
    
    
        and mn.Sy_Data_Source_Type=#{params.syDataSourceType}
    
    
        and INSTR(mn.Sy_Create_Name,#{params.syCreateName})
    
    
        and INSTR(mn.Sy_Update_Name,#{params.syUpdateName})
    
    
        and INSTR(mn.T_Code,#{params.tCode})
    
    
        and INSTR(mn.Sy_Version,#{params.syVersion})
    
    
        and INSTR(mn.Sy_Name,#{params.syName})
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Sy_Create_Time desc
